create table if not exists public.subscriptions(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,plan_id text not null default 'free',status text not null default 'active',source text,payment_request_id uuid,started_at timestamptz not null default now(),expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.payment_requests(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,plan_id text not null,amount_inr numeric not null check(amount_inr>=0),utr text not null,payer_name text,payer_upi text,status text not null default 'pending',review_note text,reviewed_by uuid references auth.users(id) on delete set null,reviewed_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index if not exists payment_requests_unique_pending_utr on public.payment_requests(utr) where status in ('pending','approved');
create table if not exists public.usage_counters(id uuid primary key default gen_random_uuid(),owner_id uuid not null references auth.users(id) on delete cascade,month_key text not null,kind text not null,used integer not null default 0 check(used>=0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(owner_id,month_key,kind));
alter table public.subscriptions enable row level security; alter table public.payment_requests enable row level security; alter table public.usage_counters enable row level security;
drop policy if exists subscription_owner_read on public.subscriptions; create policy subscription_owner_read on public.subscriptions for select using(owner_id=auth.uid());
drop policy if exists payment_owner_read on public.payment_requests; create policy payment_owner_read on public.payment_requests for select using(owner_id=auth.uid());
drop policy if exists payment_owner_insert on public.payment_requests; create policy payment_owner_insert on public.payment_requests for insert with check(owner_id=auth.uid());
drop policy if exists usage_owner_read on public.usage_counters; create policy usage_owner_read on public.usage_counters for select using(owner_id=auth.uid());
create index if not exists subscriptions_owner_status_created on public.subscriptions(owner_id,status,created_at desc); create index if not exists payment_requests_owner_created on public.payment_requests(owner_id,created_at desc); create index if not exists usage_counters_owner_month on public.usage_counters(owner_id,month_key);
